             expect(s.view).toEqual(state.view);
         });
     });
+
+    describe("view_order_reversed", () => {
+        const add = (st, id) =>
+            reduceFlows(
+                st,
+                flowActions.FLOWS_ADD({
+                    flow: { ...TFlow(), id },
+                    matching_filters: {},
+                }),
+            );
+        const ids = (st) => st.view.map((f) => f.id);
+        const opt = (value: boolean) => ({
+            view_order_reversed: { value } as any,
+        });
+
+        it("reads the option", () => {
+            let st = reduceFlows(state, {
+                type: "OPTIONS_RECEIVE",
+                payload: opt(true),
+            });
+            expect(st.view_order_reversed).toBe(true);
+            st = reduceFlows(st, {
+                type: "OPTIONS_UPDATE",
+                payload: opt(false),
+            });
+            expect(st.view_order_reversed).toBe(false);
+        });
+        it("inserts new flows at the front when reversed", () => {
+            let st = reduceFlows(state, {
+                type: "OPTIONS_UPDATE",
+                payload: opt(true),
+            });
+            st = add(add(st, "5"), "6");
+            expect(ids(st)).toEqual(["6", "5", "0", "1", "2", "3", "4"]);
+            expect(st.list.map((f) => f.id).slice(-2)).toEqual(["5", "6"]);
+            expect(st._viewIndex.get("0")).toBe(2);
+        });
+        it("inserts new flows at the back when not reversed", () => {
+            expect(ids(add(state, "5"))).toEqual([
+                "0",
+                "1",
+                "2",
+                "3",
+                "4",
+                "5",
+            ]);
+        });
+        it("prefers an active column sort", () => {
+            let st = reduceFlows(state, {
+                type: "OPTIONS_UPDATE",
+                payload: opt(true),
+            });
+            st = reduceFlows(
+                st,
+                flowActions.setSort({ column: "path", desc: false }),
+            );
+            st = add(st, "5");
+            expect(ids(st)).toEqual(["0", "1", "2", "3", "4", "5"]);
+        });
+    });
 });

